local users = tool('list_users', {})
local days = {"2026-06-15", "2026-06-16", "2026-06-17"}
local out = {}
for _, d in ipairs(days) do
  out[d] = {}
  for _, u in ipairs(users) do
    local a = tool('get_availability', { user_id = u.id, date = d })
    out[d][u.id] = a.busy or {}
  end
end
return { users = users, busy = out }
